const { RangeError } = require('range-error');

class TokenBucket {
  constructor({ capacity, refillPerSecond, now }) {
    if (typeof capacity !== 'number' || !Number.isFinite(capacity) || capacity <= 0) {
      throw new RangeError('capacity must be a positive finite number');
    }
    if (typeof refillPerSecond !== 'number' || !Number.isFinite(refillPerSecond) || refillPerSecond < 0) {
      throw new RangeError('refillPerSecond must be a non-negative finite number');
    }

    this.capacity = capacity;
    this.refillPerSecond = refillPerSecond;
    this.now = now ?? Date.now();
    this.tokens = capacity;
    this.lastRefillTime = this.now;
  }

  tryTake(n = 1) {
    if (n < 0 || !Number.isFinite(n)) {
      throw new RangeError('n must be a positive finite number');
    }

    const now = Date.now();
    const elapsedSeconds = (now - this.lastRefillTime) / 1000;

    // Dolum hesaba katmak için en son güncellenen saati kullanıyoruz
    this.lastRefillTime = now;

    if (elapsedSeconds < 0) {
      return false;
    }

    const refillAmount = elapsedSeconds * this.refillPerSecond;
    let newTokens = this.tokens + refillAmount;

    // En fazla capacity'ye kadar doldur
    if (newTokens > this.capacity) {
      newTokens = this.capacity;
    }

    this.tokens = newTokens;
    this.lastRefillTime = now;

    return this.tokens >= n;
  }

  available() {
    const now = Date.now();
    const elapsedSeconds = (now - this.lastRefillTime) / 1000;

    if (elapsedSeconds < 0) {
      return this.capacity;
    }

    const refillAmount = elapsedSeconds * this.refillPerSecond;
    let newTokens = this.tokens + refillAmount;

    // En fazla capacity'ye kadar doldur
    if (newTokens > this.capacity) {
      newTokens = this.capacity;
    }

    return Math.floor(newTokens);
  }

  msUntil(n = 1) {
    const now = Date.now();
    const elapsedSeconds = (now - this.lastRefillTime) / 1000;

    if (elapsedSeconds < 0) {
      return Infinity;
    }

    // Dolum hızı 0 ise, jeton yetmez
    if (this.refillPerSecond === 0) {
      return Infinity;
    }

    const neededTokens = n - this.tokens;

    if (neededTokens <= 0) {
      return Math.floor(0); // Yeterli, şimdi kullanabilir
    }

    const timeToRefillSeconds = neededTokens / this.refillPerSecond;
    const msUntilRefill = timeToRefillSeconds * 1000;

    if (msUntilRefill === Infinity) {
      return Infinity;
    }

    // Yavaşsa, n jeton kullanmak için geçen süreyi hesapla
    const totalTimeSeconds = elapsedSeconds + msUntilRefill;
    const totalTimeMs = Math.floor(totalTimeSeconds * 1000);

    if (totalTimeMs === Infinity) {
      return Infinity;
    }

    // Yavaşsa, n jeton kullanmak için geçen süreyi hesapla
    const timeToRefillSeconds = neededTokens / this.refillPerSecond;
    const msUntilRefill = timeToRefillSeconds * 1000;

    if (msUntilRefill === Infinity) {
      return Infinity;
    }

    // Yavaşsa, n jeton kullanmak için geçen süreyi hesapla
    const totalTimeMs = Math.floor((elapsedSeconds + msUntilRefill) * 1000);

    return Math.ceil(totalTimeMs / 1000);
  }
}

module.exports = { TokenBucket };

